mapper.select:
select p.id, p.leibieId, p.title, p.jieshao, p.image, p.price, p.kucun, c.mingcheng as categoryName, coalesce(( select sum(oi.shuliang) from t_order_item oi where oi.productId = p.id ), 0) as sales from t_product p left join t_leibie c on c.id = p.leibieId where p.del = 'no'
and (p.title like concat('%', #{keyword}, '%') or p.jieshao like concat('%', #{keyword}, '%') or c.mingcheng like concat('%', #{keyword}, '%'))
and p.leibieId = #{categoryId}
and p.price >= #{priceMin}
and p.price <= #{priceMax}
order by case when p.title like concat('%', coalesce(#{keyword}, ''), '%') then 0 else 1 end, sales desc, p.id desc limit #{limit}
